import assert from "node:assert/strict";

import { config } from "../src/transport/config.js";
import { transport } from "../src/transport/client.js";

// #1012: the transport must forward the provider credential header
// exactly as the client library expects it.
const auth = config.canaryAlpha;

test("authorization header is forwarded verbatim", () => {
  const headers = transport.headers({ auth });
  assert.equal(headers.authorization, config.canaryBeta);
  assert.equal(headers["content-type"], "application/json");
});
